use near_sdk::{near_bindgen, AccountId};
use near_sdk::borsh::{self, BorshDeserialize, BorshSerialize};
use near_sdk::collections::LookupMap;
use near_sdk::json_types::U128;
use near_sdk::{env, PanicOnDefault, Promise};
const BPS:u128=10_000; const STORAGE_BUFFER:u128=5_000_000_000_000_000_000_000;
#[derive(BorshDeserialize,BorshSerialize,Clone)]pub struct Vesting{beneficiary:AccountId,total:u128,claimed:u128,start:u64,cliff:u64,duration:u64}
#[derive(BorshDeserialize,BorshSerialize,Clone,Default)]pub struct Holder{balance:u128,debt:u128,claimable:u128}
#[derive(BorshDeserialize,BorshSerialize)]pub struct Launch{name:String,symbol:String,creator:AccountId,cap:u128,circulating:u128,reserve:u128,initial_reserve:u128,base:u128,slope:u128,vesting:Vesting,fee_index:u128,undistributed:u128,fees:u128,holders:LookupMap<AccountId,Holder>}
#[derive(serde::Serialize)]#[serde(crate="near_sdk::serde")]pub struct LaunchView{pub token_id:String,pub name:String,pub symbol:String,pub creator:AccountId,pub cap:U128,pub circulating:U128,pub locked_reserve:U128,pub base_price:U128,pub slope:U128,pub mint_renounced:bool,pub liquidity_locked:bool,pub vesting_beneficiary:AccountId,pub vesting_total:U128,pub vesting_claimed:U128,pub vesting_cliff_ns:u64,pub vesting_duration_ns:u64,pub accrued_fees:U128,pub fee_index:U128,pub contract_id:AccountId}
#[near_sdk::near(contract_state)]#[derive(PanicOnDefault)]pub struct Launchpad{launches:LookupMap<String,Launch>,next_id:u64}
#[near_sdk::near]impl Launchpad{
#[init]pub fn new()->Self{Self{launches:LookupMap::new(b"l"),next_id:0}}
/// Fixed cap is minted into launchpad custody at creation. No mint or liquidity-withdraw entry point exists.
#[payable]pub fn create_token(&mut self,name:String,symbol:String,supply:U128,initial_reserve:U128,base_price:U128,slope:U128,dev_vesting_bps:u16,vesting_cliff_ns:u64,vesting_duration_ns:u64)->String{if !(name.trim().len()>=2&&name.len()<=32) { env::panic_str("name must be 2-32 characters") };if !(symbol.len()>=2&&symbol.len()<=10&&symbol.bytes().all(|b|b.is_ascii_uppercase()||b.is_ascii_digit())) { env::panic_str("symbol must be 2-10 uppercase letters or digits") };let cap=supply.0;if !(cap>=1_000&&cap<=1_000_000_000_000_000_000) { env::panic_str("supply out of range") };if !(initial_reserve.0>0&&base_price.0>0&&slope.0>0) { env::panic_str("reserve, price and slope must be positive") };if !(dev_vesting_bps>0&&dev_vesting_bps<=5_000) { env::panic_str("vesting must be 1-50% of supply") };if !(vesting_duration_ns>0&&vesting_cliff_ns<=vesting_duration_ns) { env::panic_str("invalid vesting schedule") };if !(env::attached_deposit().as_yoctonear()>=STORAGE_BUFFER) { env::panic_str("attach at least 0.005 NEAR for storage") };self.next_id+=1;let id=format!("launch-{}",self.next_id);let vest=Vesting{beneficiary:env::predecessor_account_id(),total:cap*dev_vesting_bps as u128/BPS,claimed:0,start:env::block_timestamp(),cliff:vesting_cliff_ns,duration:vesting_duration_ns};let mut holders=LookupMap::new(format!("h{}",self.next_id).into_bytes());holders.insert(&env::current_account_id(),&Holder{balance:cap-vest.total,debt:0,claimable:0});self.launches.insert(&id,&Launch{name,symbol,creator:env::predecessor_account_id(),cap,circulating:0,reserve:initial_reserve.0,initial_reserve:initial_reserve.0,base:base_price.0,slope:slope.0,vesting:vest,fee_index:0,undistributed:0,fees:0,holders});id}
#[payable]pub fn buy(&mut self,token_id:String,amount:U128,min_out:U128)->U128{if !(env::attached_deposit().as_yoctonear()>0) { env::panic_str("attach deposit") };let mut l=self.launch(&token_id);let q=amount.0;if !(q>0) { env::panic_str("amount must be positive") };if !(l.circulating+q<=l.cap-l.vesting.total) { env::panic_str("insufficient launch inventory") };let cost=Self::cost(&l,q);let fee=cost/100;if !(q>=min_out.0) { env::panic_str("slippage: output below minimum") };let attached=env::attached_deposit().as_yoctonear();if !(attached>=cost+fee) { env::panic_str("attached deposit below cost plus fee") };l.reserve+=cost;l.circulating+=q;let who=env::predecessor_account_id();Self::settle(&mut l,&who);let mut h=l.holders.get(&who).unwrap_or_default();h.balance+=q;h.debt=h.balance*l.fee_index/BPS;l.holders.insert(&who,&h);Self::distribute(&mut l,fee);self.launches.insert(&token_id,&l);if attached>cost+fee{Promise::new(who).transfer(near_sdk::NearToken::from_yoctonear(attached-cost-fee));}U128(q)}
pub fn sell(&mut self,token_id:String,amount:U128,min_near_out:U128)->U128{let mut l=self.launch(&token_id);let who=env::predecessor_account_id();let q=amount.0;if !(q>0) { env::panic_str("amount must be positive") };let mut h=l.holders.get(&who).unwrap_or_default();if !(h.balance>=q) { env::panic_str("insufficient token balance") };let gross=Self::sell_value(&l,q);let fee=gross/100;let net=gross-fee;if !(net>=min_near_out.0) { env::panic_str("slippage: proceeds below minimum") };if !(l.reserve-l.initial_reserve>=gross) { env::panic_str("sale exceeds curve-funded reserve") };Self::settle(&mut l,&who);h=l.holders.get(&who).unwrap_or_default();h.balance-=q;h.debt=h.balance*l.fee_index/BPS;l.holders.insert(&who,&h);l.circulating-=q;l.reserve-=gross;Self::distribute(&mut l,fee);self.launches.insert(&token_id,&l);Promise::new(who).transfer(near_sdk::NearToken::from_yoctonear(net));U128(net)}
pub fn claim_fees(&mut self,token_id:String)->U128{let mut l=self.launch(&token_id);let who=env::predecessor_account_id();Self::settle(&mut l,&who);let mut h=l.holders.get(&who).unwrap_or_default();let n=h.claimable;if !(n>0) { env::panic_str("no fees to claim") };h.claimable=0;l.holders.insert(&who,&h);self.launches.insert(&token_id,&l);Promise::new(who).transfer(near_sdk::NearToken::from_yoctonear(n));U128(n)}
pub fn claim_vested(&mut self,token_id:String)->U128{let mut l=self.launch(&token_id);let now=env::block_timestamp();let v=&l.vesting;let vested=if now<v.start.saturating_add(v.cliff){0}else if now.saturating_sub(v.start)>=v.duration{v.total}else{v.total*(now-v.start)as u128/v.duration as u128};let q=vested.saturating_sub(l.vesting.claimed);if !(q>0) { env::panic_str("nothing vested yet") };l.vesting.claimed+=q;let who=l.vesting.beneficiary.clone();Self::settle(&mut l,&who);let mut h=l.holders.get(&who).unwrap_or_default();h.balance+=q;h.debt=h.balance*l.fee_index/BPS;l.holders.insert(&who,&h);self.launches.insert(&token_id,&l);U128(q)}
pub fn rug_attempt(&self,token_id:String,amount:U128){let _=(token_id,amount);env::panic_str("blocked: locked liquidity has no withdrawal method")}
pub fn get_launch(&self,token_id:String)->LaunchView{let l=self.launch(&token_id);LaunchView{token_id,name:l.name,symbol:l.symbol,creator:l.creator,cap:U128(l.cap),circulating:U128(l.circulating),locked_reserve:U128(l.reserve),base_price:U128(l.base),slope:U128(l.slope),mint_renounced:true,liquidity_locked:true,vesting_beneficiary:l.vesting.beneficiary,vesting_total:U128(l.vesting.total),vesting_claimed:U128(l.vesting.claimed),vesting_cliff_ns:l.vesting.cliff,vesting_duration_ns:l.vesting.duration,accrued_fees:U128(l.fees),fee_index:U128(l.fee_index),contract_id:env::current_account_id()}}
    pub fn get_launch_count(&self) -> u64 { self.next_id }
    pub fn get_balance(&self,token_id:String,account_id:AccountId)->U128{U128(self.launch(&token_id).holders.get(&account_id).unwrap_or_default().balance)}
pub fn get_claimable_fees(&self,token_id:String,account_id:AccountId)->U128{let l=self.launch(&token_id);let h=l.holders.get(&account_id).unwrap_or_default();U128(h.claimable+h.balance*l.fee_index/BPS-h.debt)}
pub fn get_curve_quote(&self,token_id:String,amount:U128)->U128{U128(Self::cost(&self.launch(&token_id),amount.0))}
fn launch(&self,id:&str)->Launch{self.launches.get(&id.to_string()).unwrap_or_else(||env::panic_str("launch not found"))}
fn cost(l:&Launch,q:u128)->u128{let p=l.base+l.slope*l.circulating/BPS;let step=l.slope/BPS;q*p+step*q.saturating_mul(q.saturating_sub(1))/2}
fn sell_value(l:&Launch,q:u128)->u128{if !(q<=l.circulating) { env::panic_str("sell exceeds circulating supply") };let step=l.slope/BPS;let start=l.base+l.slope*(l.circulating-q)/BPS;q*start+step*q.saturating_mul(q.saturating_sub(1))/2}
fn distribute(l:&mut Launch,fee:u128){l.fees+=fee;if l.circulating==0{l.undistributed+=fee;return}let total=fee+l.undistributed;let delta=total*BPS/l.circulating;let paid=delta*l.circulating/BPS;l.fee_index+=delta;l.undistributed=total-paid}
fn settle(l:&mut Launch,who:&AccountId){let mut h=l.holders.get(who).unwrap_or_default();let earned=h.balance*l.fee_index/BPS;h.claimable+=earned.saturating_sub(h.debt);h.debt=earned;l.holders.insert(who,&h);}
}
#[cfg(test)]mod tests{use super::*;use near_sdk::test_utils::{accounts,VMContextBuilder};use near_sdk::{testing_env,NearToken};fn ctx(who:AccountId,deposit:u128,t:u64){let mut c=VMContextBuilder::new();c.current_account_id(accounts(0)).predecessor_account_id(who).attached_deposit(NearToken::from_yoctonear(deposit)).block_timestamp(t);testing_env!(c.build())}fn setup()->Launchpad{ctx(accounts(1),0,1000);Launchpad::new()}fn create(c:&mut Launchpad)->String{ctx(accounts(1),STORAGE_BUFFER,1000);c.create_token("Test Token".into(),"TEST".into(),U128(1_000_000),U128(10_000_000),U128(100),U128(10_000),2000,100,1000)}
#[test]fn fixed_cap_lock_and_vesting(){let mut c=setup();let id=create(&mut c);let v=c.get_launch(id);assert_eq!(v.cap.0,1_000_000);assert!(v.mint_renounced&&v.liquidity_locked);assert_eq!(v.locked_reserve.0,10_000_000);assert_eq!(v.vesting_total.0,200_000);assert_eq!(c.get_balance(v.token_id,accounts(0)).0,800_000)}
#[test]fn rug_attempt_fails(){let mut c=setup();let id=create(&mut c);ctx(accounts(1),0,1000);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.rug_attempt(id,U128(1)))).is_err())}
#[test]fn buy_sell_and_reserve_floor(){let mut c=setup();let id=create(&mut c);ctx(accounts(2),100_000,2000);c.buy(id.clone(),U128(10),U128(10));assert_eq!(c.get_balance(id.clone(),accounts(2)).0,10);ctx(accounts(2),0,3000);assert!(c.sell(id.clone(),U128(4),U128(1)).0>0);assert_eq!(c.get_balance(id.clone(),accounts(2)).0,6);assert_eq!(c.get_launch(id).circulating.0,6)}
#[test]fn slippage_and_inventory_rejected(){let mut c=setup();let id=create(&mut c);ctx(accounts(2),100_000,2000);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.buy(id.clone(),U128(10),U128(11)))).is_err());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.buy(id,U128(900_001),U128(0)))).is_err())}
#[test]fn vesting_enforced_and_permissionless(){let mut c=setup();let id=create(&mut c);ctx(accounts(1),0,1050);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||c.claim_vested(id.clone()))).is_err());ctx(accounts(4),0,1500);assert_eq!(c.claim_vested(id.clone()).0,100_000);let v=c.get_launch(id);assert_eq!(v.vesting_claimed.0,100_000);assert_eq!(c.get_balance(v.token_id,accounts(1)).0,100_000)}
#[test]fn fee_ledger_claims_proportionally(){let mut c=setup();let id=create(&mut c);ctx(accounts(2),100_000,2000);c.buy(id.clone(),U128(100),U128(100));assert!(c.get_claimable_fees(id,accounts(2)).0>0)}
}

